import numpy as np, scipy.optimize as so
def mk(S,dp=3):
    fs=[S, np.ones_like(t), t]
    return np.column_stack([f*P**j for f in fs for j in range(dp+1)])
def loss_tanh(p):
    b,t0=p
    A=mk(np.tanh(b*(t-t0)))
    c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]
    return np.mean((dP_dt-A@c)**2)/np.var(dP_dt)
def loss_exp(p):
    b,t0=p
    A=mk(1-np.exp(-b*(t-t0)))
    c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]
    return np.mean((dP_dt-A@c)**2)/np.var(dP_dt)
for nm_,L in [('tanh',loss_tanh),('exp',loss_exp)]:
    best=None
    for b0 in [0.2,0.5,1.0]:
        for t0 in [-2,0,1,3]:
            r=so.minimize(L,[b0,t0],method='Nelder-Mead',options={'maxiter':300,'xatol':1e-7,'fatol':1e-13})
            if best is None or r.fun<best.fun: best=r
    print(nm_,best.x,best.fun)

import numpy as np, scipy.optimize as so
def build2(b,g,dp,extra):
    fs=[np.tanh(b*t), np.exp(-g*t), t*np.exp(-g*t), np.ones_like(t), t]
    if extra: fs.append(t*np.tanh(b*t))
    return np.column_stack([f*P**j for f in fs for j in range(dp+1)])
def L(p,dp,extra):
    A=build2(abs(p[0])+1e-6,abs(p[1])+1e-6,dp,extra)
    c=np.linalg.lstsq(A,dP_dt,rcond=None)[0]
    return np.mean((dP_dt-A@c)**2)/np.var(dP_dt)
for dp,extra in [(2,False),(3,False),(2,True)]:
    r=so.minimize(L,[0.234,0.36],args=(dp,extra),method='Nelder-Mead',options={'maxiter':300,'xatol':1e-8,'fatol':1e-14})
    print(dp,extra,r.x,r.fun)
